"use strict";(globalThis.webpackChunkelemental_selenium||=[]).push([[34219],{495865(e){e.exports=JSON.parse('{"tag":{"label":"multiple browsers","permalink":"/tips/tags/multiple-browsers","allTagsPath":"/tips/tags","count":3,"items":[{"id":"one-test-multiple-browsers/41-one-test-multiple-browsers","title":"How to Run a Test on Multiple Browsers","description":"You\'ll occasionally have something that you want to test across multiple browsers. It would be nice to run your test once and have it execute against all the browsers you care about. Unfortunately this functionality doesn\'t come out of the box with most testing frameworks.","permalink":"/tips/41-one-test-multiple-browsers"},{"id":"one-test-multiple-browsers-parallel/42-one-test-multiple-browsers-parallel","title":"How to Run a Test on Multiple Browsers, In Parallel","description":"In the previous tip I covered how to run a single test against multiple browsers. While this could come in handy, it is still a bit lacking.","permalink":"/tips/42-one-test-multiple-browsers-parallel"},{"id":"two-users-at-once/76-two-users-at-once","title":"How to Test Two Users at Once","description":"A chat, a shared document or a multiplayer game only works when one user sees what another user does. One test can start two browsers, one for each user, and check that a message sent by one user reaches the other.","permalink":"/tips/76-two-users-at-once"}],"unlisted":false}}')}}]);